const request = $input.first().json;
const body = request.body ?? request;
const transcript = body.transcript;

if (typeof transcript !== 'string' || transcript.trim().length < 20) {
  throw new Error('Le champ transcript est requis et doit contenir au moins 20 caractères.');
}

const normalized = transcript.replace(/\r\n/g, '\n').trim();
const maxCharacters = 12000;
const paragraphs = normalized.split(/\n{2,}/);
const chunks = [];
let current = '';

for (const paragraph of paragraphs) {
  if (paragraph.length > maxCharacters) {
    if (current) {
      chunks.push(current);
      current = '';
    }
    for (let start = 0; start < paragraph.length; start += maxCharacters) {
      chunks.push(paragraph.slice(start, start + maxCharacters));
    }
    continue;
  }

  const candidate = current ? `${current}\n\n${paragraph}` : paragraph;
  if (candidate.length > maxCharacters) {
    chunks.push(current);
    current = paragraph;
  } else {
    current = candidate;
  }
}

if (current) chunks.push(current);

return chunks.map((chunk, index) => ({
  json: {
    segment_index: index,
    nombre_segments: chunks.length,
    source: body.source ?? null,
    texte: chunk
  }
}));

const schema = {
  segment_index: $json.segment_index,
  dossiers: [{
    participants: [],
    type_transaction: null,
    objectif: null,
    emploi: [],
    revenus: [],
    dettes: [],
    prix_achat_envisage: null,
    mise_de_fonds_envisagee: null,
    documents_requis: [],
    taches: [],
    prochaines_actions: [],
    points_a_valider: [],
    faits: [{
      champ: null,
      valeur: null,
      preuve: null,
      horodatage: null,
      confiance: 'faible|moyenne|elevee'
    }]
  }],
  conversation_distincte_detectee: false,
  avertissements: []
};

const prompt = [
  'Tu extrais uniquement des faits CRM hypothécaires propres aux clients.',
  'Retourne exclusivement un objet JSON valide respectant le schéma fourni.',
  'N’invente aucune valeur et ne transforme pas un exemple général ou une information sur le courtier en donnée client.',
  'Pour chaque fait, copie dans preuve un extrait VERBATIM de 5 à 200 caractères présent dans TRANSCRIPTION, sans le reformuler et sans ajouter de préambule.',
  'N’ajoute dans faits que les informations propres aux clients. Une information sans extrait exact va dans points_a_valider.',
  'Une information inaudible ou ambiguë va dans points_a_valider.',
  'Signale si le segment contient une conversation ou un dossier distinct.',
  `Segment ${$json.segment_index + 1} sur ${$json.nombre_segments}.`,
  `SCHÉMA: ${JSON.stringify(schema)}`,
  `TRANSCRIPTION:\n${$json.texte}`
].join('\n\n');

return {
  json: {
    segment_index: $json.segment_index,
    nombre_segments: $json.nombre_segments,
    texte: $json.texte,
    prompt
  }
};

const texte = String($json.texte ?? '');
const groupesMotsCles = [
  /\b(emploi|employé|employe|employeur|profession|comptable|étudiant|etudiant|doctorat|temps partiel|contrat)\b/gi,
  /\b(salaire|revenu|dette|mise de fonds|document|avis de cotisation)\b/gi
];
const extraits = [];
const plages = [];

for (const motsCles of groupesMotsCles) {
  let correspondance;

  while ((correspondance = motsCles.exec(texte)) !== null && extraits.length < 25) {
    const debut = Math.max(0, correspondance.index - 180);
    const fin = Math.min(texte.length, correspondance.index + correspondance[0].length + 320);
    const chevauche = plages.some((plage) => debut < plage.fin && fin > plage.debut);

    if (chevauche) {
      continue;
    }

    extraits.push(texte.slice(debut, fin).trim());
    plages.push({ debut, fin });
  }
}

if (extraits.length === 0) {
  return { json: $json };
}

return {
  json: {
    ...$json,
    prompt: [
      'EXTRAITS CRM PRIORITAIRES COPIES VERBATIM DU SEGMENT :',
      ...extraits,
      'FIN DES EXTRAITS PRIORITAIRES.',
      '',
      $json.prompt
    ].join('\n')
  }
};

let parsed;

try {
  parsed = typeof $json.response === 'string'
    ? JSON.parse($json.response)
    : $json.response;
} catch (error) {
  return {
    json: {
      ...$json,
      normalisation_erreur: error.message
    }
  };
}

if (!parsed || !Array.isArray(parsed.dossiers)) {
  return { json: $json };
}

const collections = [
  'faits',
  'emploi',
  'revenus',
  'dettes',
  'documents_requis',
  'taches',
  'prochaines_actions'
];

for (const dossier of parsed.dossiers) {
  const faits = [];
  const dejaVus = new Set();

  for (const collection of collections) {
    const candidats = Array.isArray(dossier?.[collection])
      ? dossier[collection]
      : [];

    for (const candidat of candidats) {
      if (!candidat || typeof candidat !== 'object') continue;

      let fait = collection === 'faits'
        ? { ...candidat }
        : { ...candidat, categorie_source: collection };

      if (collection === 'documents_requis'
        && (fait.valeur === null || fait.valeur === undefined)
        && typeof fait.champ === 'string'
        && fait.champ.trim() !== '') {
        fait = { ...fait, champ: 'document_requis', valeur: fait.champ };
      }

      if (collection === 'prochaines_actions'
        && (fait.valeur === null || fait.valeur === undefined)
        && typeof fait.champ === 'string'
        && fait.champ.trim() !== '') {
        fait = { ...fait, champ: 'prochaine_action', valeur: fait.champ };
      }

      const cle = JSON.stringify([
        fait.champ ?? null,
        fait.valeur ?? null,
        fait.preuve ?? null,
        fait.horodatage ?? null
      ]);

      if (!dejaVus.has(cle)) {
        dejaVus.add(cle);
        faits.push(fait);
      }
    }
  }

  dossier.faits = faits;
}

return {
  json: {
    ...$json,
    response: JSON.stringify(parsed)
  }
};

const sourceSegments = $('Valider et découper').all();

const normalize = (value) => String(value ?? '')
  .normalize('NFKD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  .toLowerCase();

const champsAutorises = new Set([
  'profession', 'statut_emploi', 'statut_etudes', 'revenu', 'dette',
  'mise_de_fonds', 'mise_de_fonds_envisagee', 'prix_achat',
  'prix_achat_envisage', 'type_transaction', 'objectif',
  'document_requis', 'documents_requis', 'prochaine_action',
  'prochaines_actions'
]);

const analyses = $input.all().map((item, index) => {
  try {
    const parsed = typeof item.json.response === 'string'
      ? JSON.parse(item.json.response)
      : item.json.response;
    const source = sourceSegments[index]?.json?.texte ?? '';
    const normalizedSource = normalize(source);
    const dossiers = Array.isArray(parsed?.dossiers) ? parsed.dossiers : [];
    const faits = dossiers.flatMap((dossier) =>
      Array.isArray(dossier?.faits) ? dossier.faits : []
    );

    const faitsValides = [];
    const faitsRejetes = [];

    for (const fait of faits) {
      const preuve = typeof fait?.preuve === 'string' ? fait.preuve.trim() : '';
      const preuveNormalisee = normalize(preuve);
      const champNormalise = normalize(fait?.champ).replace(/ /g, '_');
      const champAutorise = champsAutorises.has(champNormalise);
      const preuveRetrouvee = preuve.length >= 5
        && normalizedSource.includes(preuveNormalisee);
      const structureValide = typeof fait?.champ === 'string'
        && fait.champ.trim() !== ''
        && fait.valeur !== null
        && fait.valeur !== undefined;
      const preuveHypothetique = /\b(mettons|par exemple|exemple|supposons|imaginons|si tu gagnes|regle facile)\b/i
        .test(preuveNormalisee);
      const preuveCourtier = /\bje suis (devenu )?courtier hypothecaire\b/i
        .test(preuveNormalisee);

      if (preuveRetrouvee && structureValide && champAutorise && !preuveHypothetique && !preuveCourtier) {
        faitsValides.push({ ...fait, preuve_verifiee: true });
      } else {
        faitsRejetes.push({
          ...fait,
          preuve_verifiee: false,
          motif_rejet: !structureValide
            ? 'champ ou valeur absent'
            : !champAutorise
              ? 'champ hors contrat CRM'
              : preuveHypothetique
                ? 'preuve issue d’un exemple ou d’une hypothèse'
                : preuveCourtier
                  ? 'information propre au courtier, pas au client'
                  : 'preuve absente du segment source'
        });
      }
    }

    const professionsExplicites = source.matchAll(/\b([A-ZÀ-ÖØ-Þ][A-Za-zÀ-ÖØ-öø-ÿ'’-]+)\s+lui est\s+([A-Za-zÀ-ÖØ-öø-ÿ'’-]+)/g);
    for (const correspondance of professionsExplicites) {
      const preuve = correspondance[0];
      const existe = faitsValides.some((fait) =>
        normalize(fait.champ) === 'profession' && normalize(fait.preuve) === normalize(preuve)
      );

      if (!existe) {
        faitsValides.push({
          champ: 'profession',
          sujet: correspondance[1],
          valeur: correspondance[2],
          preuve,
          confiance: 'elevee',
          methode_extraction: 'regle_explicitement_verifiee',
          preuve_verifiee: true
        });
      }
    }

    return {
      segment_index: parsed?.segment_index ?? index,
      valide_json: true,
      utilisable_pour_crm: faitsValides.length > 0,
      faits_valides: faitsValides,
      faits_rejetes: faitsRejetes,
      suggestions_modele_non_validees: parsed
    };
  } catch (error) {
    return {
      segment_index: index,
      valide_json: false,
      utilisable_pour_crm: false,
      faits_valides: [],
      faits_rejetes: [],
      suggestions_modele_non_validees: null,
      erreur: error.message
    };
  }
});

const invalides = analyses.filter((segment) => !segment.valide_json).length;
const faitsValides = analyses.reduce(
  (total, segment) => total + segment.faits_valides.length,
  0
);

return [{
  json: {
    statut: invalides === 0 ? 'prevalidation_terminee' : 'analyse_partielle',
    nombre_segments: analyses.length,
    segments_invalides: invalides,
    nombre_faits_valides: faitsValides,
    ecriture_crm_effectuee: false,
    validation_humaine_requise: true,
    analyses,
    avertissements: [
      'Seuls les faits_valides possèdent une preuve retrouvée dans le texte source.',
      'Les suggestions_modele_non_validees ne doivent jamais alimenter le CRM.',
      'La fusion et la résolution des contradictions exigent une validation humaine.'
    ]
  }
}];
